void ZeroPad(IMG_ARR_T Image_with_Noise, PADDED_IMG_ARR_T Padded_Image) {

  Zeros(Padded_Image);

  for (int i = 0; i < IMAGE_ROWS; i++) {
   for (int j = 0; j < IMAGE_COLUMNS; j++) {
      Padded_Image[i + 1][j + 1] = Image_with_Noise[i][j];
    }
  }

}

